import { PlayerId } from "@bloxd"

declare const __brand: unique symbol
type Branded<T, B> = T & { [__brand]: B }
export type TimeoutId = Branded<number, "TimeoutId">
export type IntervalId = Branded<number, "IntervalId">

let nextTimeoutId: number = 1
let nextIntervalId: number = 1
type Callback = {
	callback: () => void
	callAt: number
	interval?: number
	playerId?: PlayerId
}
const timeouts: Record<TimeoutId, Callback> = {}
const intervals: Record<IntervalId, Callback> = {}

/**
 * Registers a function to be called after a delay.
 * @param callback - The callback to call when the timeout expires
 * @param delay - The delay in milliseconds before the callback is called
 * @param playerId - Optional playerId to tie the timeout to. If the player leaves, this timeout will be cleared
 * @returns The timeout id
 */
export function setTimeout(callback: () => void, delay: number, playerId?: PlayerId): TimeoutId {
	const id = nextTimeoutId++
	timeouts[id] = { callback, callAt: api.now() + delay, playerId }
	return id as TimeoutId
}

/**
 * Registers a function to be called repeatedly every interval.
 * @param callback - The callback to call when the interval expires
 * @param interval - The interval in milliseconds before the callback is called
 * @param playerId - Optional playerId to tie the interval to. If the player leaves, this interval will be stopped
 * @returns The interval id
 */
export function setInterval(callback: () => void, interval: number, playerId?: PlayerId): IntervalId {
	const id = nextIntervalId++
	intervals[id] = { callback, callAt: api.now() + interval, interval, playerId }
	return id as IntervalId
}

/**
 * Clears a timeout.
 * @param id - The id of the timeout to clear
 */
export function clearTimeout(id: TimeoutId) {
	delete timeouts[id]
}

/**
 * Clears an interval.
 * @param id - The id of the interval to clear
 */
export function clearInterval(id: IntervalId) {
	delete intervals[id]
}

export function handleTimers() {
	const now = api.now()
	for (const timeoutId in timeouts) {
		const callback = timeouts[timeoutId]
		if (callback.callAt <= now) {
			if (!callback.playerId || api.checkValid(callback.playerId)) {
				try {
					callback.callback()
				} catch (e) {
					api.log(`Error in timeout callback ${timeoutId}: ${e}`)
				}
			}
			delete timeouts[timeoutId]
		}
	}
	for (const intervalId in intervals) {
		const callback = intervals[intervalId]
		if (callback.callAt <= now) {
			if (callback.playerId && !api.checkValid(callback.playerId)) {
				delete intervals[intervalId]
				continue
			}

			try {
				callback.callback()
			} catch (e) {
				api.log(`Error in interval callback ${intervalId}: ${e}`)
			}
			callback.callAt += callback.interval
		}
	}
}
